import{_ as o,o as a,c as n,aa as t}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/academy/img/opravnene-osoby/01.webp",r="/buildary-help-preview/media/cs/diary/loga_grafika.png",d="/buildary-help-preview/academy/img/opravnene-osoby/08.webp",s="/buildary-help-preview/academy/img/opravnene-osoby/06.webp",l="/buildary-help-preview/media/cs/diary/opravneneosoby2.png",k="/buildary-help-preview/media/cs/diary/doklady_stavby.png",u="/buildary-help-preview/media/cs/diary/titulni_list1.png",p="/buildary-help-preview/media/cs/diary/titulni_list2..png",f=JSON.parse('{"title":"Identifikační údaje deníku","description":"","frontmatter":{"title":"Identifikační údaje deníku","wiki":"cs:diary:diaryidentification"},"headers":[],"relativePath":"diary/diaryidentification.md","filePath":"diary/diaryidentification.md","lastUpdated":1794209661000}'),v={name:"diary/diaryidentification.md"};function m(y,e,h,b,g,c){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="identifikacni-udaje-deniku" tabindex="-1">Identifikační údaje deníku <a class="header-anchor" href="#identifikacni-udaje-deniku" aria-label="Permalink to &quot;Identifikační údaje deníku&quot;">​</a></h1><p>Identifikační údaje tvoří část A stavebního deníku: úvodní list s údaji o stavbě a deníku, loga, seznam oprávněných osob a dokumenty deníku. Otevřete je v levém panelu volbou <strong>Identifikační údaje</strong>.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/opravnene-osoby">Přidat oprávněnou osobu do deníku</a> v Akademii.</p><h2 id="co-identifikacni-udaje-obsahuji" tabindex="-1">Co identifikační údaje obsahují <a class="header-anchor" href="#co-identifikacni-udaje-obsahuji" aria-label="Permalink to &quot;Co identifikační údaje obsahují&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Záložka</th><th>Co v ní je</th></tr></thead><tbody><tr><td><strong>Úvodní list deníku</strong></td><td>Typ deníku, kdo ho vede, doklad, na jehož základě se stavba realizuje, a termíny deníku.</td></tr><tr><td><strong>Loga a grafika</strong></td><td>Loga a titulní obrázek, které se tisknou na úvodní listy deníku.</td></tr><tr><td><strong>Oprávněné osoby</strong></td><td>Kdo deník vede a kdo do něj smí zapisovat, a v jaké roli.</td></tr><tr><td><strong>Dokumenty deníku</strong></td><td>Základní doklady, projektová dokumentace, kontroly a zkoušky a ostatní dokumenty stavby.</td></tr><tr><td><strong>Nastavení deníku</strong></td><td>Podpisy, pracovní doba a obsah sekcí – viz <a href="/buildary-help-preview/diary/diarysettings">Nastavit deník</a>.</td></tr></tbody></table><h2 id="uvodni-list-deniku" tabindex="-1">Úvodní list deníku <a class="header-anchor" href="#uvodni-list-deniku" aria-label="Permalink to &quot;Úvodní list deníku&quot;">​</a></h2><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Záložka Úvodní list deníku" loading="lazy"></figure><p>Úvodní list obsahuje stejné údaje, jaké jste vyplnili při založení deníku. Můžete je kdykoli upravit a změny uložit. Význam jednotlivých polí popisuje <a href="/buildary-help-preview/diary/diarysetup">Založit deník</a>.</p><h2 id="loga-a-grafika" tabindex="-1">Loga a grafika <a class="header-anchor" href="#loga-a-grafika" aria-label="Permalink to &quot;Loga a grafika&quot;">​</a></h2><figure class="shot" style="--w:640px;"><img src="'+r+'" alt="Záložka Loga a grafika s hlavním a doplňkovým logem a titulním obrázkem" loading="lazy"></figure><ul><li><strong>Hlavní logo firmy</strong> (nejvýše 120 × 100 px) – tiskne se vlevo nahoře. U nového deníku se převezme z <a href="/buildary-help-preview/firstofall/domain">firemní domény</a>.</li><li><strong>Doplňkové logo firmy</strong> (nejvýše 120 × 100 px) – tiskne se vpravo nahoře. U nového deníku je předvyplněné.</li><li><strong>Titulní obrázek</strong> (doporučeně 720 × 379 px) – obrázek na titulní straně deníku. Vyberte jeden z nabízených tlačítkem <strong>Vybrat</strong>, nebo nahrajte vlastní tlačítkem <strong>Nahrát</strong>. Obrázek jiné velikosti se přizpůsobí.</li></ul><p>Loga jsou na tmavém pruhu, proto se hodí bílá loga s průhledným pozadím (například PNG).</p><h2 id="opravnene-osoby" tabindex="-1">Oprávněné osoby <a class="header-anchor" href="#opravnene-osoby" aria-label="Permalink to &quot;Oprávněné osoby&quot;">​</a></h2><p>Oprávněné osoby jsou lidé, kteří ve smyslu zákona deník vedou nebo do něj smějí zapisovat – stavbyvedoucí, technický dozor stavebníka, autorský dozor, koordinátor BOZP a další. Každá oprávněná osoba může celý deník prohlížet. Co v něm smí dělat dál, určuje její role, viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</p><p>Do deníku přidáváte jen členy projektového týmu stavby. Člověka, který v týmu ještě není, nejdřív přidejte do <a href="/buildary-help-preview/diary/projectteam">projektového týmu</a>.</p><figure class="shot" style="--w:760px;"><img src="'+d+'" alt="Seznam oprávněných osob deníku" loading="lazy"></figure><h3 id="pridat-opravnenou-osobu" tabindex="-1">Přidat oprávněnou osobu <a class="header-anchor" href="#pridat-opravnenou-osobu" aria-label="Permalink to &quot;Přidat oprávněnou osobu&quot;">​</a></h3><p>Na záložce <strong>Oprávněné osoby</strong> klikněte na <strong>Přidat</strong> a vyplňte:</p><table tabindex="0"><thead><tr><th>Pole</th><th>Co znamená</th></tr></thead><tbody><tr><td><strong>Příjmení a jméno</strong></td><td>Výběr z členů projektového týmu.</td></tr><tr><td><strong>Role</strong></td><td>Předvyplní se výchozí role člena v projektovém týmu. V každém deníku může mít tentýž člověk jinou roli.</td></tr><tr><td><strong>E-mailové oznámení o přidání dalšího záznamu</strong></td><td>Osoba dostane e-mail o každém novém Dalším záznamu v deníku.</td></tr><tr><td><strong>Neuvádět v PDF výstupu</strong></td><td>Osoba se nevypíše v seznamu oprávněných osob v PDF deníku.</td></tr><tr><td><strong>Nahrát přílohu</strong></td><td>Doklad o oprávnění k vybraným činnostem, viz <a href="#opravneni-k-vybranym-cinnostem">Oprávnění k vybraným činnostem</a>.</td></tr></tbody></table><figure class="shot" style="--w:760px;"><img src="'+s+'" alt="Formulář Přidání oprávněné osoby" loading="lazy"></figure><p>Tlačítkem <strong>Kopíruj oprávněné osoby</strong> převezmete oprávněné osoby z jiného deníku stavby. Oprávněné osoby lze zkopírovat i při zakládání deníku kopií, viz <a href="/buildary-help-preview/diary/diarysetup#novy-denik-nebo-kopie">Založit deník</a>.</p><p>Kdo deník založil, je mezi oprávněnými osobami automaticky jako administrátor. Jako vlastník deníku má práva administrátora vždy – odebráním ani změnou role ho omezit nejde.</p><h3 id="opravneni-k-vybranym-cinnostem" tabindex="-1">Oprávnění k vybraným činnostem <a class="header-anchor" href="#opravneni-k-vybranym-cinnostem" aria-label="Permalink to &quot;Oprávnění k vybraným činnostem&quot;">​</a></h3><p>Osoby, u kterých to zákon vyžaduje, otiskují do úvodních listů deníku autorizační razítko a připojují vlastnoruční podpis. V Buildary to uděláte takto:</p><ol><li>Otevřete oprávněnou osobu ikonou tužky a volbou <strong>Stažení formuláře</strong> si stáhněte první stránku deníku.</li><li>Doplňte do ní razítko a podpis – nejlépe elektronické.</li><li>Dokument nahrajte k osobě jako přílohu.</li></ol><p>Pokud použijete fyzické razítko, dokument nejdřív převeďte autorizovanou konverzí do elektronické podoby a nahrajte až ten.</p><p>Příloha se automaticky připojí k úvodním listům deníku v PDF, takže se stane součástí elektronického deníku.</p><figure class="shot" style="--w:640px;"><img src="'+l+'" alt="Oprávněná osoba v PDF deníku s přiloženým oprávněním" loading="lazy"></figure><h2 id="dokumenty-deniku" tabindex="-1">Dokumenty deníku <a class="header-anchor" href="#dokumenty-deniku" aria-label="Permalink to &quot;Dokumenty deníku&quot;">​</a></h2><p>Záložka <strong>Dokumenty deníku</strong> má čtyři části: <strong>Základní doklady</strong>, <strong>Projektová dokumentace</strong>, <strong>Kontroly a zkoušky</strong> a <strong>Ostatní dokumenty</strong>. Do každé zapisujete doklady a dokumenty, které se stavby týkají – předmět, označení (číslo jednací), datum, kdo je vydal, formu a poznámku. Ke každému záznamu můžete přiložit i soubor.</p><figure class="shot" style="--w:760px;"><img src="'+k+'" alt="Záložka Dokumenty deníku, část Projektová dokumentace" loading="lazy"></figure><p>Zapisovat sem smí oprávněná osoba s kompetencí <strong>Dokumenty stavby</strong>, viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>. Všechny přiložené soubory stáhnete najednou tlačítkem <strong>Stažení příloh dokumentů deníku</strong>.</p><h2 id="identifikacni-udaje-v-pdf" tabindex="-1">Identifikační údaje v PDF <a class="header-anchor" href="#identifikacni-udaje-v-pdf" aria-label="Permalink to &quot;Identifikační údaje v PDF&quot;">​</a></h2><p>Tlačítkem <strong>Stažení Identifikačních údajů</strong> vpravo nahoře si kdykoli stáhnete úvodní listy deníku v PDF: titulní stranu, údaje o stavbě a deníku, účastníky stavby s oprávněnými osobami a dokumenty deníku.</p><div class="gallery"><figure class="shot"><img src="'+u+'" alt="Titulní strana a úvodní list deníku v PDF" loading="lazy"></figure><figure class="shot"><img src="'+p+'" alt="Účastníci stavby, oprávněné osoby a dokumenty deníku v PDF" loading="lazy"></figure></div><p>Celý deník včetně denních záznamů vytisknete podle návodu <a href="/buildary-help-preview/diary/download">Tisk a export deníku</a>.</p>',36)])])}const z=o(v,[["render",m]]);export{f as __pageData,z as default};
